const {run,isSep}=require('/tmp/probe-casing/lib.js');
const all=[];
for(let cp=1; cp<=0x10FFFF; cp++){
  if(cp>=0xD800&&cp<=0xDFFF) continue;
  if(isSep(cp)) continue;
  all.push(cp);
}
console.log('total cps to test', all.length);
function expect(cps){ return cps.map(c=>String.fromCodePoint(c)).join('_').toLowerCase()+'\n'; }
function value(cps){ return cps.map(c=>String.fromCodePoint(c)).join('!'); }
function check(cps){
  const r=run(value(cps));
  if(r.status!==0) return {ok:false, err:'status '+r.status+' '+r.err.toString()};
  const ok = r.out.equals(Buffer.from(expect(cps),'utf8'));
  return {ok, out:r.out};
}
const bad=[];
function bisect(cps){
  if(cps.length===1){ bad.push(cps[0]); return; }
  const mid=cps.length>>1;
  const a=cps.slice(0,mid), b=cps.slice(mid);
  const ra=check(a), rb=check(b);
  if(!ra.ok) bisect(a);
  if(!rb.ok) bisect(b);
  if(ra.ok&&rb.ok){ /* interaction-only: report whole */ bad.push({interaction:cps.slice(0,20), len:cps.length}); }
}
const B=8000;
let calls=0;
for(let i=0;i<all.length;i+=B){
  const batch=all.slice(i,i+B);
  const r=check(batch); calls++;
  if(!r.ok){ console.log('MISMATCH batch starting U+'+batch[0].toString(16)); bisect(batch); }
}
console.log('calls',calls);
console.log('BAD count', bad.length);
console.log(JSON.stringify(bad.map(b=> typeof b==='number' ? 'U+'+b.toString(16).toUpperCase().padStart(4,'0') : b)));
