for(let cp=1; cp<=0x10FFFF; cp++){
  if(cp>=0xD800&&cp<=0xDFFF) continue;
  if(isSep(cp)) continue;
  all.push(cp);
}
function sweep(name, mk){
  const bad=[];
  function check(cps){
    const pieces=cps.map(mk);
    const r=run(pieces.join('!'));
    if(r.status!==0) return {ok:false};
    return {ok: r.out.equals(Buffer.from(pieces.join('_').toLowerCase()+'\n','utf8'))};
  }
  function bisect(cps){
    if(cps.length===1){bad.push(cps[0]);return;}
    const m=cps.length>>1, a=cps.slice(0,m), b=cps.slice(m);
    const ra=check(a), rb=check(b);
    if(!ra.ok)bisect(a); if(!rb.ok)bisect(b);
    if(ra.ok&&rb.ok) bad.push({interaction:cps.length});
  }
  const B=4000;
  for(let i=0;i<all.length;i+=B){
    const batch=all.slice(i,i+B);
    if(!check(batch).ok){ bisect(batch); }
  }
  console.log(name,'BAD',bad.length, JSON.stringify(bad.slice(0,50).map(b=>typeof b==='number'?'U+'+b.toString(16).toUpperCase():b)));
}
